    R6 = R14 AND R6;                                    // !(n & 1) ?
    IF EQ R4 = R5 OR R5;
    R6 = DM(3, I4);
    COMP(F0, F6);                                       // drum_amplitude_ > 0.03f ?
    IF GT R4 = R5 OR R5;
    F0 = F0 * F4;                                       // drum_amplitude_ *=
    R15 = PASS R15;                                     // hold_counter_ ?
    IF EQ JUMP _ss_decay;
    R15 = R15 - 1;
    JUMP _ss_held;
_ss_decay:
    R4 = DM(1, I4);
    F1 = F1 * F4;                                       // snare_amplitude_ *= snare_decay
_ss_held:
    R4 = DM(2, I4);
    F2 = F2 * F4, R4 = DM(0, I1);                       // fm_ *= fm_decay; phase_[0]
    R6 = DM(4, I4);
    R7 = DM(6, I4);
    R8 = DM(5, I4);
    COMP(F4, F8);                                       // phase_[0] > 0.5f ? -1.0f : 1.0f
    R9 = R6 OR R6;
    R5 = DM(1, I1);
    COMP(F4, F8);
    IF GT R9 = R7 OR R7;
    R10 = DM(14, I4);
    F9 = F10 + F9;                                      // reset_noise = 0.0f + ..
    R10 = R6 OR R6;
    COMP(F5, F8);                                       // phase_[1] > 0.5f ?
    IF GT R10 = R7 OR R7;
    F9 = F9 + F10, R10 = DM(7, I4);
    F9 = F9 * F10;                                      // reset_noise *= reset_noise_amount * 0.025f
    R10 = DM(10, I4);
    F10 = F10 * F2, R11 = DM(9, I4);                    // 4.0f * fm_
    F10 = F11 * F10;                                    // fm_amount * (..)
    F10 = F6 + F10, R11 = DM(8, I4);                    // 1.0f + ..
    F10 = F11 * F10, R11 = DM(11, I4);                  // f
    F4 = F4 + F10;                                      // phase_[0] += f
    F11 = F10 * F11;                                    // f * 1.47f
    F5 = F5 + F11, R10 = DM(24, I4);                    // phase_[1] +=
    R11 = DM(18, I4);
    COMP(F10, F11);                                     // reset_noise_amount > 0.1f ?
    IF LE JUMP _ss_wrap;
    F10 = F6 + F9;                                      // 1.0f + reset_noise
    F11 = F6 - F4;                                      // 1.0f - phase_[0]
    COMP(F4, F10);
    IF GE R4 = R11 OR R11;
    F11 = F6 - F5;
    COMP(F5, F10);
    IF GE R5 = R11 OR R11;
    JUMP _ss_wrapped;
_ss_wrap:
    COMP(F4, F6);                                       // phase_[i] >= 1.0f: -= 1.0f
    IF GE F4 = F4 - F6;
    COMP(F5, F6);
    IF GE F5 = F5 - F6;
_ss_wrapped:
    DM(0, I1) = R4;
    DM(1, I1) = R5;
    R5 = DM(4, I4);
    F5 = F5 - F4, R6 = DM(5, I4);                       // 1.0f - phase
    R7 = R4 OR R4;
    COMP(F4, F6);                                       // phase < 0.5f ?
    IF GE R7 = R5 OR R5;
    R6 = DM(10, I4);
    F7 = F7 * F6, R6 = DM(12, I4);                      // * 4.0f
    F7 = F7 - F6, R6 = DM(13, I4);                      // - 1.3f: triangle
    F11 = F6 * F7, R10 = DM(14, I4);                    // 2.0f * triangle
    F12 = -F7;
    COMP(F7, F10);
    IF GE R12 = R7 OR R7;
    R4 = DM(4, I4);
    F12 = F4 + F12;                                     // 1.0f + absf(triangle)
    R10 = R6 OR R6;                                     // 2.0f
    F5 = RECIPS F12, R12 = R12;
    F8 = F12 * F5;                                      // DistortedSine
    F8 = F10 - F8;
    F5 = F5 * F8;
    F8 = F12 * F5;
    F8 = F10 - F8;
    F5 = F5 * F8;
    F10 = F11 * F5;
    F8 = F12 * F10;
    F8 = F11 - F8;
    F8 = F8 * F5;
    F9 = F10 + F8;
    R10 = DM(15, I4);
    F9 = F9 * F10, R3 = DM(25, I4);                     // DistortedSine(phase_[0]) * 0.60f; drum = -0.1f
    F3 = F3 + F9, R4 = DM(1, I1);
    R5 = DM(4, I4);
    F5 = F5 - F4, R6 = DM(5, I4);                       // 1.0f - phase
    R7 = R4 OR R4;
    COMP(F4, F6);                                       // phase < 0.5f ?
    IF GE R7 = R5 OR R5;
    R6 = DM(10, I4);
    F7 = F7 * F6, R6 = DM(12, I4);                      // * 4.0f
    F7 = F7 - F6, R6 = DM(13, I4);                      // - 1.3f: triangle
    F11 = F6 * F7, R10 = DM(14, I4);                    // 2.0f * triangle
    F12 = -F7;
    COMP(F7, F10);
    IF GE R12 = R7 OR R7;
    R4 = DM(4, I4);
    F12 = F4 + F12;                                     // 1.0f + absf(triangle)
    R10 = R6 OR R6;                                     // 2.0f
    F5 = RECIPS F12, R12 = R12;
    F8 = F12 * F5;                                      // DistortedSine
    F8 = F10 - F8;
    F5 = F5 * F8;
    F8 = F12 * F5;
    F8 = F10 - F8;
    F5 = F5 * F8;
    F10 = F11 * F5;
    F8 = F12 * F10;
    F8 = F11 - F8;
    F8 = F8 * F5;
    F9 = F10 + F8;
    R10 = DM(16, I4);
    F9 = F9 * F10, R10 = DM(17, I4);                    // * 0.25f
    F3 = F3 + F9;
    F10 = F0 * F10;                                     // drum_amplitude_ * drum_level
    F3 = F3 * F10, R4 = DM(6, I1);                      // drum *=
    F4 = F4 * F3, R5 = DM(8, I1);                       // one_pole_low_pass: g * in
    F4 = F4 + F5, R6 = DM(7, I1);                       // + state
    F4 = F4 * F6, R5 = DM(6, I1);                       // lp
    F6 = F3 - F4;                                       // in - lp
    F6 = F5 * F6;                                       // g * ..
    F6 = F6 + F4;                                       // + lp
    R3 = PASS R4, DM(8, I1) = R6;                       // drum
    R4 = 1664525;
    R5 = 1013904223;
    R13 = R13 * R4 (SSI), R6 = DM(20, I4);              // rng_word
    R13 = R13 + R5;
    R7 = FEXT R13 BY 16:16;                             // w >> 16
    R8 = FEXT R13 BY 0:16;                              // w & 0xFFFF
    R7 = R7 OR R6;                                      // itof_nonneg
    R8 = R8 OR R6;
    F7 = F7 - F6, R5 = DM(21, I4);
    F8 = F8 - F6;
    F7 = F7 * F5, R5 = DM(22, I4);                      // hi * 65536.0f
    F7 = F7 + F8, R6 = DM(23, I4);                      // + lo
    F8 = F7 * F5;                                       // / 4294967296.0f: q
    F4 = F6 * F8;
    F4 = F7 - F4;
    F4 = F4 * F5;
    F11 = F8 + F4;
    R4 = DM(13, I1);                                    // svf_step: r
    R5 = DM(15, I1);                                    // state_1
    F9 = F4 * F5, R6 = DM(12, I1);                      // r * state_1; g
    F10 = F11 - F9, R7 = DM(16, I1);                    // ; state_2
    F9 = F6 * F5, R8 = DM(14, I1);                      // g * state_1; h
    F10 = F10 - F9;
    F10 = F10 - F7;
    F10 = F10 * F8;                                     // hp
    F9 = F6 * F10;                                      // g * hp
    F4 = F9 + F5;                                       // bp
    F5 = F9 + F4;                                       // state_1
    F9 = F6 * F4;                                       // g * bp
    F8 = F9 + F7;                                       // lp
    F7 = F9 + F8, DM(15, I1) = R5;                      // state_2
    DM(16, I1) = R7;
    R4 = DM(9, I1);
    F4 = F4 * F8, R5 = DM(11, I1);                      // one_pole_high_pass: g * in
    F4 = F4 + F5, R6 = DM(10, I1);
    F4 = F4 * F6, R5 = DM(9, I1);                       // lp
    F6 = F8 - F4;                                       // in - lp
    F6 = F5 * F6;
    F6 = F6 + F4;
    F8 = F8 - F4, DM(11, I1) = R6;                      // snare = in - lp
    R4 = DM(18, I4);
    F8 = F8 + F4;                                       // snare + 0.1f
    F4 = F1 + F2, R5 = DM(19, I4);                      // snare_amplitude_ + fm_
    F8 = F8 * F4;
    F8 = F8 * F5;                                       // * snare_level
    F8 = F8 + F3;                                       // snare + drum
_ss_end:
    DM(I0, M6) = R8;
_ss_done:
    DM(5, I1) = R15;
    DM(2, I1) = R0;
    DM(3, I1) = R1;
    DM(4, I1) = R2;
    I2 = DM(2, I6);
    DM(0, I2) = R13;
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,6)(NW);
    L4 = DM(1, I7);
    L2 = DM(2, I7);
    L1 = DM(3, I7);
    L0 = DM(4, I7);
    M6 = DM(5, I7);
    I2 = DM(6, I7);
    I1 = DM(7, I7);
    I0 = DM(8, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;

// ---- hat_square_noise_kernel(unsigned int *phase, const unsigned int *increment, float *out, int size,
// const float *k): SquareNoise::Render's loop. Phases in R0-R3, R13, R14, increments in R15, R9-R12, R7
.GLOBAL hat_square_noise_kernel.;
hat_square_noise_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = I2;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L2;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L2 = 0;
    L4 = 0;
    I7=MODIFY (I7,-6)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I1 = R4;
    I2 = R8;
    I0 = R12;
    I4 = DM(2, I6);                                     // k
    R0 = DM(0, I1);
    R15 = DM(0, I2);
    R1 = DM(1, I1);
    R9 = DM(1, I2);
    R2 = DM(2, I1);
    R10 = DM(2, I2);
    R3 = DM(3, I1);
    R11 = DM(3, I2);
    R13 = DM(4, I1);
    R12 = DM(4, I2);
    R14 = DM(5, I1);
    R7 = DM(5, I2);
    R4 = DM(1, I6);                                     // size
    R5 = 0;
    COMP(R4, R5);
    IF LE JUMP _hq_done;
    LCNTR = R4, DO _hq_end UNTIL LCE;
    R0 = R0 + R15;                                      // phase[0] += increment[0]
    R1 = R1 + R9;                                       // phase[1] += increment[1]
    R2 = R2 + R10;                                      // phase[2] += increment[2]
    R3 = R3 + R11;                                      // phase[3] += increment[3]
    R13 = R13 + R12;                                    // phase[4] += increment[4]
    R14 = R14 + R7;                                     // phase[5] += increment[5]
    R4 = FEXT R0 BY 31:1;                               // noise += phase >> 31
    R5 = FEXT R1 BY 31:1;
    R4 = R4 + R5;
    R5 = FEXT R2 BY 31:1;
    R4 = R4 + R5;
    R5 = FEXT R3 BY 31:1;
    R4 = R4 + R5;
    R5 = FEXT R13 BY 31:1;
    R4 = R4 + R5;
    R5 = FEXT R14 BY 31:1;
    R4 = R4 + R5;
    R5 = DM(0, I4);
    R4 = R4 OR R5, R6 = DM(1, I4);                      // itof_nonneg(noise)
    F4 = F4 - F5;
    F4 = F6 * F4, R6 = DM(2, I4);                       // 0.33f * ..
    F4 = F4 - F6;                                       // - 1.0f
_hq_end:
    DM(I0, M6) = R4;
_hq_done:
    DM(0, I1) = R0;
    DM(1, I1) = R1;
    DM(2, I1) = R2;
    DM(3, I1) = R3;
    DM(4, I1) = R13;
    DM(5, I1) = R14;
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,6)(NW);
    L4 = DM(1, I7);
    L2 = DM(2, I7);
    L1 = DM(3, I7);
    L0 = DM(4, I7);
    M6 = DM(5, I7);
    I2 = DM(6, I7);
    I1 = DM(7, I7);
    I0 = DM(8, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;

// ---- hat_square_kernel(HatOscillator *o, const float *k, float *out, int size, const float *t1):
// R0 phase_, R1 next_sample, R2 high_, R3/R13 frequency value/increment, R14/R15 pw value/increment;
// I1 = o, I4 = k, I0 = out
.GLOBAL hat_square_kernel.;
hat_square_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = I2;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L2;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L2 = 0;
    L4 = 0;
    I7=MODIFY (I7,-6)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I1 = R4;
    I4 = R8;
    I0 = R12;
    R0 = DM(0, I1);
    R1 = DM(1, I1);
    R2 = DM(4, I1);
    R3 = DM(5, I1);
    R13 = DM(0, I4);
    R14 = DM(6, I1);
    R15 = DM(1, I4);
    R4 = DM(1, I6);                                     // size
    R5 = 0;
    COMP(R4, R5);
    IF LE JUMP _hs_done;
    LCNTR = R4, DO _hs_end UNTIL LCE;
    R4 = PASS R1, R1 = DM(6, I4);                       // this_sample = next_sample; next_sample = 0.0f
    F3 = F3 + F13;                                      // f = next(&fm)
    F14 = F14 + F15;                                    // w = next(&pwm)
    F0 = F0 + F3;                                       // phase_ += f
    R5 = 0;
    R6 = 1;
    COMP(F0, F14);                                      // phase_ >= w
    IF GE R5 = R6 OR R6;
    COMP(R5, R2);                                       // high_ ^ (..) == 0 ?
    IF EQ JUMP _hs_noedge;
    R2 = PASS R5;                                       // high_ = phase_ >= w
    F9 = F0 - F14, R10 = DM(5, I4);                     // phase_ - w
    F6 = RECIPS F3, R3 = R3;
    F7 = F3 * F6;                                       // t = (phase_ - w) / f
    F7 = F10 - F7;
    F6 = F6 * F7;
    F7 = F3 * F6;
    F7 = F10 - F7;
    F6 = F6 * F7;
    F10 = F9 * F6;
    F7 = F3 * F10;
    F7 = F9 - F7;
    F7 = F7 * F6;
    F9 = F10 + F7;
    R8 = DM(3, I4);
    F11 = F8 * F9, R8 = DM(2, I4);                      // ThisBlepSample: 0.5f * t
    F11 = F11 * F9;                                     // * t
    F12 = F8 - F9, R8 = DM(4, I4);                      // NextBlepSample: t = 1.0f - t
    F8 = F8 * F12;                                      // -0.5f * t
    F12 = F8 * F12;                                     // * t
    R8 = DM(2, I4);
    F11 = F11 * F8;                                     // ThisBlepSample(t) * 1.0f
    F4 = F4 + F11;                                      // this_sample +=
    F12 = F12 * F8;                                     // NextBlepSample(t) * 1.0f
    F1 = F1 + F12;                                      // next_sample +=
_hs_noedge:
    R8 = DM(2, I4);
    COMP(F0, F8);                                       // phase_ >= 1.0f ?
    IF LT JUMP _hs_nowrap;
    F0 = F0 - F8, R10 = DM(5, I4);                      // phase_ -= 1.0f
    F6 = RECIPS F3, R3 = R3;
    F7 = F3 * F6;                                       // t = phase_ / f
    F7 = F10 - F7;
    F6 = F6 * F7;
    F7 = F3 * F6;
    F7 = F10 - F7;
    F6 = F6 * F7;
    F10 = F0 * F6;
    F7 = F3 * F10;
    F7 = F0 - F7;
    F7 = F7 * F6;
    F9 = F10 + F7;
    R8 = DM(3, I4);
    F11 = F8 * F9, R8 = DM(2, I4);                      // ThisBlepSample: 0.5f * t
    F11 = F11 * F9;                                     // * t
    F12 = F8 - F9, R8 = DM(4, I4);                      // NextBlepSample: t = 1.0f - t
    F8 = F8 * F12;                                      // -0.5f * t
    F12 = F8 * F12;                                     // * t
    F4 = F4 - F11;                                      // this_sample -= ThisBlepSample(t)
    F1 = F1 - F12;                                      // next_sample -= NextBlepSample(t)
    R2 = 0;                                             // high_ = 0
_hs_nowrap:
    R5 = DM(6, I4);
    R6 = DM(2, I4);
    COMP(F0, F14);                                      // phase_ < w ? 0.0f : 1.0f
    IF GE R5 = R6 OR R6;
    F1 = F1 + F5;                                       // next_sample +=
    R5 = DM(5, I4);
    F4 = F5 * F4, R5 = DM(2, I4);                       // 2.0f * this_sample
    F4 = F4 - F5;                                       // - 1.0f
_hs_end:
    DM(I0, M6) = R4;
_hs_done:
    DM(0, I1) = R0;
    DM(1, I1) = R1;
    DM(4, I1) = R2;
    DM(5, I1) = R3;                                     // commit(&fm)
    DM(6, I1) = R14;                                    // commit(&pwm)
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,6)(NW);
    L4 = DM(1, I7);
    L2 = DM(2, I7);
    L1 = DM(3, I7);
    L0 = DM(4, I7);
    M6 = DM(5, I7);
    I2 = DM(6, I7);
    I1 = DM(7, I7);
    I0 = DM(8, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;

// ---- hat_saw_kernel(HatOscillator *o, const float *k, float *out, int size, const float *t1):
// R0 phase_, R1 next_sample, R2 high_, R3/R13 frequency value/increment, R14/R15 pw value/increment;
// I1 = o, I4 = k, I0 = out, I2 = t1 (out[n] += t1[n] * saw)
.GLOBAL hat_saw_kernel.;
hat_saw_kernel.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = I2;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L2;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L2 = 0;
    L4 = 0;
    I7=MODIFY (I7,-6)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I1 = R4;
    I4 = R8;
    I0 = R12;
    I2 = DM(2, I6);                                     // t1
    R0 = DM(0, I1);
    R1 = DM(1, I1);
    R2 = DM(4, I1);
    R3 = DM(5, I1);
    R13 = DM(0, I4);
    R14 = DM(6, I1);
    R15 = DM(1, I4);
    R4 = DM(1, I6);                                     // size
    R5 = 0;
    COMP(R4, R5);
    IF LE JUMP _hw_done;
    LCNTR = R4, DO _hw_end UNTIL LCE;
    R4 = PASS R1, R1 = DM(6, I4);                       // this_sample = next_sample; next_sample = 0.0f
    F3 = F3 + F13;                                      // f = next(&fm)
    F14 = F14 + F15;                                    // w = next(&pwm)
    F0 = F0 + F3;                                       // phase_ += f
    R8 = DM(2, I4);
    COMP(F0, F8);                                       // phase_ >= 1.0f ?
    IF LT JUMP _hw_nowrap;
    F0 = F0 - F8, R10 = DM(5, I4);                      // phase_ -= 1.0f
    F6 = RECIPS F3, R3 = R3;
    F7 = F3 * F6;                                       // t = phase_ / f
    F7 = F10 - F7;
    F6 = F6 * F7;
    F7 = F3 * F6;
    F7 = F10 - F7;
    F6 = F6 * F7;
    F10 = F0 * F6;
    F7 = F3 * F10;
    F7 = F0 - F7;
    F7 = F7 * F6;
    F9 = F10 + F7;
    R8 = DM(3, I4);
    F11 = F8 * F9, R8 = DM(2, I4);                      // ThisBlepSample: 0.5f * t
    F11 = F11 * F9;                                     // * t
    F12 = F8 - F9, R8 = DM(4, I4);                      // NextBlepSample: t = 1.0f - t
    F8 = F8 * F12;                                      // -0.5f * t
    F12 = F8 * F12;                                     // * t
    F4 = F4 - F11;                                      // this_sample -= ThisBlepSample(t)
    F1 = F1 - F12;                                      // next_sample -= NextBlepSample(t)
_hw_nowrap:
    F1 = F1 + F0;                                       // next_sample += phase_
    R5 = DM(5, I4);
    F4 = F5 * F4, R5 = DM(2, I4);                       // 2.0f * this_sample
    F4 = F4 - F5;                                       // - 1.0f
    R5 = DM(I2, M6);                                    // temp_1[n]
    F4 = F5 * F4, R5 = DM(0, I0);                       // temp_1[n] * temp_2[n]; out[n]
    F4 = F5 + F4;                                       // out[n] +=
_hw_end:
    DM(I0, M6) = R4;
_hw_done:
    DM(0, I1) = R0;
    DM(1, I1) = R1;
    DM(5, I1) = R3;                                     // commit(&fm)
    DM(6, I1) = R14;                                    // commit(&pwm)
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,6)(NW);
    L4 = DM(1, I7);
    L2 = DM(2, I7);
    L1 = DM(3, I7);
    L0 = DM(4, I7);
    M6 = DM(5, I7);
    I2 = DM(6, I7);
    I1 = DM(7, I7);
    I0 = DM(8, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;

// ---- hat_tail_kernel0(HiHat *s, float *k, float *out, int size, unsigned int *rng): hat_render's loops after
// the noise source, fused per sample. R13 rng, R14 envelope_, R15 noise_clock_, R0 noise_sample_, R1/R2
// the coloration states, R3/R11 the high pass states; I1 = s, I4 = k, I0 = out
.GLOBAL hat_tail_kernel0.;
hat_tail_kernel0.:
    R0 = I0;
    DM(I7, M7) = R0;
    R0 = I1;
    DM(I7, M7) = R0;
    R0 = I2;
    DM(I7, M7) = R0;
    R0 = M6;
    DM(I7, M7) = R0;
    R0 = L0;
    DM(I7, M7) = R0;
    R0 = L1;
    DM(I7, M7) = R0;
    R0 = L2;
    DM(I7, M7) = R0;
    R0 = L4;
    DM(I7, M7) = R0;
    M6 = 1;
    L0 = 0;
    L1 = 0;
    L2 = 0;
    L4 = 0;
    I7=MODIFY (I7,-6)(NW);
    DM(1, I7) = R9;
    DM(2, I7) = R10;
    DM(3, I7) = R11;
    DM(4, I7) = R13;
    DM(5, I7) = R14;
    DM(6, I7) = R15;
    I1 = R4;
    I4 = R8;
    I0 = R12;
    R8 = DM(13, I4);
    R4 = DM(9, I4);
    F9 = RECIPS F8, R8 = R8;
    F10 = F8 * F9;
    F10 = F4 - F10;
    F9 = F9 * F10;
    F10 = F8 * F9;
    F10 = F4 - F10;
    F9 = F9 * F10;
    DM(12, I4) = R9;
    I2 = DM(2, I6);                                     // rng
    R13 = DM(0, I2);
    R14 = DM(0, I1);
    R15 = DM(1, I1);
    R0 = DM(2, I1);
    R1 = DM(6, I1);
    R2 = DM(7, I1);
    R3 = DM(11, I1);
    R11 = DM(12, I1);
    R4 = DM(1, I6);                                     // size
    R5 = 0;
    COMP(R4, R5);
    IF LE JUMP _ht0_done;
    LCNTR = R4, DO _ht0_end UNTIL LCE;
    R5 = DM(4, I1);                                     // band pass: r
    F9 = F5 * F1, R4 = DM(0, I0);                       // r * state_1; in
    F10 = F4 - F9, R6 = DM(3, I1);                      // ; g
    F9 = F6 * F1, R7 = DM(5, I1);                       // g * state_1; h
    F10 = F10 - F9;
    F10 = F10 - F2;
    F10 = F10 * F7;                                     // hp
    F9 = F6 * F10;                                      // g * hp
    F12 = F9 + F1;                                      // bp: out[n]
    F1 = F9 + F12;                                      // state_1
    F9 = F6 * F12;                                      // g * bp
    F8 = F9 + F2;                                       // lp
    F2 = F9 + F8, R5 = DM(0, I4);                       // state_2
    F15 = F15 + F5, R5 = DM(1, I4);                     // noise_clock_ += noise_f
    COMP(F15, F5);                                      // noise_clock_ >= 1.0f ?
    IF LT JUMP _ht0_noclk;
    F15 = F15 - F5;
    R4 = 1664525;
    R5 = 1013904223;
    R13 = R13 * R4 (SSI), R6 = DM(10, I4);              // rng_word
    R13 = R13 + R5;
    R7 = FEXT R13 BY 16:16;                             // w >> 16
    R8 = FEXT R13 BY 0:16;                              // w & 0xFFFF
    R7 = R7 OR R6;                                      // itof_nonneg
    R8 = R8 OR R6;
    F7 = F7 - F6, R5 = DM(11, I4);
    F8 = F8 - F6;
    F7 = F7 * F5, R5 = DM(12, I4);                      // hi * 65536.0f
    F7 = F7 + F8, R6 = DM(13, I4);                      // + lo
    F8 = F7 * F5;                                       // / 4294967296.0f: q
    F4 = F6 * F8;
    F4 = F7 - F4;
    F4 = F4 * F5;
    F9 = F8 + F4;
    R10 = DM(2, I4);
    F0 = F9 - F10;                                      // noise_sample_ = rng_float - 0.5f
_ht0_noclk:
    F5 = F0 - F12, R6 = DM(3, I4);                      // noise_sample_ - out[n]
    F5 = F6 * F5;
    F12 = F12 + F5, R5 = DM(4, I4);                     // out[n] += noisiness * (..)
    F14 = F14 * F5, R5 = DM(8, I4);                     // envelope_ *= envelope_decay
    R6 = DM(7, I4);
    R10 = DM(6, I4);
    COMP(F12, F10);                                     // v > 0.0f ? 4.0f : 0.1f
    IF GT R5 = R6 OR R6;
    F12 = F12 * F5;
    F7 = -F12;
    COMP(F12, F10);
    IF GE R7 = R12 OR R12;
    R5 = DM(1, I4);
    F7 = F5 + F7, R10 = DM(9, I4);                      // 1.0f + absf(v)
    F5 = RECIPS F7, R7 = R7;
    F6 = F7 * F5;                                       // v / (..)
    F6 = F10 - F6;
    F5 = F5 * F6;
    F6 = F7 * F5;
    F6 = F10 - F6;
    F5 = F5 * F6;
    F10 = F12 * F5;
    F6 = F7 * F10;
    F6 = F12 - F6;
    F6 = F6 * F5;
    F12 = F10 + F6;
    R5 = DM(8, I4);
    F12 = F12 + F5;                                     // v + 0.1f
    F12 = F12 * F14;                                    // * envelope_
    R5 = DM(9, I1);                                     // high pass: r
    F9 = F5 * F3, R6 = DM(8, I1);                       // r * state_1; g
    F10 = F12 - F9, R7 = DM(10, I1);                    // ; h
    F9 = F6 * F3;                                       // g * state_1
    F10 = F10 - F9;
    F10 = F10 - F11;
    F10 = F10 * F7;                                     // hp: out[n]
    F9 = F6 * F10;                                      // g * hp
    F12 = F9 + F3;                                      // bp
    F3 = F9 + F12;                                      // state_1
    F9 = F6 * F12;                                      // g * bp
    F8 = F9 + F11;                                      // lp
    F11 = F9 + F8;                                      // state_2
_ht0_end:
    DM(I0, M6) = R10;
_ht0_done:
    DM(0, I1) = R14;
    DM(1, I1) = R15;
    DM(2, I1) = R0;
    DM(6, I1) = R1;
    DM(7, I1) = R2;
    DM(11, I1) = R3;
    DM(12, I1) = R11;
    I2 = DM(2, I6);
    DM(0, I2) = R13;
    R9 = DM(1, I7);
    R10 = DM(2, I7);
    R11 = DM(3, I7);
    R13 = DM(4, I7);
    R14 = DM(5, I7);
    R15 = DM(6, I7);
    I7=MODIFY (I7,6)(NW);
    L4 = DM(1, I7);
    L2 = DM(2, I7);
    L1 = DM(3, I7);
    L0 = DM(4, I7);
    M6 = DM(5, I7);
    I2 = DM(6, I7);
    I1 = DM(7, I7);
    I0 = DM(8, I7);
    I12 = DM(M7, I6);
    JUMP (M14, I12) (DB);
    RFRAME;
    NOP;

// ---- hat_tail_kernel1(HiHat *s, float *k, float *out, int size, unsigned int *rng): hat_render's loops after
