    F9 = F9 * F10;
    F10 = F8 * F9;
    F10 = F4 - F10;
    F9 = F9 * F10;
    DM(12, I4) = R9;
    I2 = DM(2, I6);                                     // rng
    R13 = DM(0, I2);
    R14 = DM(0, I1);
    R15 = DM(1, I1);
    R0 = DM(2, I1);
    R1 = DM(6, I1);
    R2 = DM(7, I1);
    R3 = DM(11, I1);
    R11 = DM(12, I1);
