    F10 = F10 - F2;
    F10 = F10 * F7;                                     // hp
    F9 = F6 * F10;                                      // g * hp
    F12 = F9 + F1;                                      // bp: out[n]
    F1 = F9 + F12;                                      // state_1
    F9 = F6 * F12;                                      // g * bp
    F8 = F9 + F2;                                       // lp
    F2 = F9 + F8, R5 = DM(0, I4);                       // state_2
    F15 = F15 + F5, R5 = DM(1, I4);                     // noise_clock_ += noise_f
    COMP(F15, F5);                                      // noise_clock_ >= 1.0f ?
    IF LT JUMP _ht1_noclk;
    F15 = F15 - F5;
    R4 = 1664525;
    R5 = 1013904223;
    R13 = R13 * R4 (SSI), R6 = DM(10, I4);              // rng_word
    R13 = R13 + R5;
    R7 = FEXT R13 BY 16:16;                             // w >> 16
